insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('personal-recipe-images','personal-recipe-images',false,2097152,array['image/webp']) on conflict(id) do update set public=false,file_size_limit=2097152,allowed_mime_types=array['image/webp'];
create policy "personal_images_select" on storage.objects for select to authenticated using (bucket_id='personal-recipe-images' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "personal_images_insert" on storage.objects for insert to authenticated with check (bucket_id='personal-recipe-images' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "personal_images_delete" on storage.objects for delete to authenticated using (bucket_id='personal-recipe-images' and (storage.foldername(name))[1]=(select auth.uid())::text);
